{% block body %}
\t<!-- SECTION : HERO -->
\t{% include 'partials/_hero.html.twig' with { title: 'CONTACT' } %}

\t<!-- SECTION : CONTACT FORM -->
\t<section class=\"container-back bg-primary py-5 mx-auto\">
\t\t<div class=\"bg-tertiary w-75 mx-auto rounded-3 p-4 p-md-5 border border-dark\">

\t\t\t{{ form_start(form) }}

\t\t\t<div class=\"mb-3\">
\t\t\t\t{{ form_label(form.title) }}
\t\t\t\t{{ form_widget(form.title) }}
\t\t\t\t{{ form_errors(form.title) }}
\t\t\t</div>

\t\t\t<div class=\"mb-3\">
\t\t\t\t{{ form_label(form.email) }}
\t\t\t\t{{ form_widget(form.email) }}
\t\t\t\t{{ form_errors(form.email) }}
\t\t\t</div>

\t\t\t<div class=\"mb-3\">
\t\t\t\t{{ form_label(form.message) }}
\t\t\t\t{{ form_widget(form.message) }}
\t\t\t\t{{ form_errors(form.message) }}
\t\t\t</div>

\t\t\t<div class=\"text-center\">
\t\t\t\t<button type=\"submit\" id=\"btn-contact\" class=\"btn btn-black mb-4\">Soumettre</button>
\t\t\t</div>
            
\t\t\t{% for message in app.flashes('success') %}
\t\t\t\t<div class=\"alert alert-success\">
\t\t\t\t\t{{ message }}
\t\t\t\t</div>
\t\t\t{% endfor %}

\t\t\t{{ form_end(form) }}

\t\t</div>
\t</section>
{% endblock %}
